DELETE FROM sys_event_outbox
WHERE service_name = #{serviceName}
  AND status = #{status}
  AND sent_time < #{sentTimeBefore}
LIMIT #{limit}

DELETE FROM sys_event_outbox
WHERE ctid IN (SELECT ctid FROM sys_event_outbox
               WHERE service_name = #{serviceName}
                 AND status = #{status}
                 AND sent_time < #{sentTimeBefore}
               LIMIT #{limit})
